import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.ContainerRegistryCleanup{RemovedContainers: []protocol.FullContainerName{{ContainerID: 7,
# DynamicContainerID: protocol.Option[uint32](9)}, {ContainerID: 2}}}
GOLDEN = bytes.fromhex("020701090000000200")

GOLDENS = [
    pytest.param(
        version.ContainerRegistryCleanupPacket(
            removed_containers=[
                version.FullContainerName(name=version.ContainerEnumName.LEVEL_ENTITY_CONTAINER, dynamic_id=9),
                version.FullContainerName(
                    name=version.ContainerEnumName.ANVIL_RESULT_PREVIEW_CONTAINER, dynamic_id=None
                ),
            ]
        ),
        GOLDEN,
        id=name,
    )
    for name, version in VERSIONS.items()
]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_container_registry_cleanup_is_packet_317(version):
    assert version.PACKETS[317] is version.ContainerRegistryCleanupPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_registry_cleanup_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_registry_cleanup_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_an_absent_dynamic_id_is_four_bytes_shorter_than_a_present_one(version):
    absent = version.ContainerRegistryCleanupPacket(
        removed_containers=[
            version.FullContainerName(name=version.ContainerEnumName.ANVIL_RESULT_PREVIEW_CONTAINER, dynamic_id=None)
        ]
    )
    present = version.ContainerRegistryCleanupPacket(
        removed_containers=[
            version.FullContainerName(name=version.ContainerEnumName.ANVIL_RESULT_PREVIEW_CONTAINER, dynamic_id=1)
        ]
    )
    assert len(bytes(absent)) == 3
    assert len(bytes(present)) == len(bytes(absent)) + 4
    assert type(present).from_bytes(bytes(present)) == present
